const root=document.querySelector('#app');let user=null;let setupRequired=false;

async function progressScreen(){
 try{
  const plans=await api('progress');
  shell(`<section class="heading"><span class="eyebrow">PREPARE WITH PURPOSE</span><h1>${user.role==='faculty'?'Student preparation progress':'My preparation tracker'}</h1><p>Work through your approved roadmap and keep evidence notes. Completion is student-reported, not a verified skill score.</p></section>${plans.length?plans.map(p=>`<section class="card report"><div class="report-top"><h2>${user.role==='faculty'?esc(p.name)+' ('+esc(p.student)+') - ':''}${esc(p.target)}</h2><span class="pill">Report #${p.id}${p.isCurrent?' · Current':' · History'}</span></div><p>${p.completed} of ${p.tasks.length} tasks completed</p>${p.tasks.length?`<progress class="roadmap-meter" value="${p.completed}" max="${p.tasks.length}" aria-label="Tasks completed"></progress>`:'<p>No tasks were included in this report. Continue assessments and project practice.</p>'}${p.tasks.map(t=>`<article class="evidence"><span class="pill">Week ${esc(t.week)} - ${esc(t.status.replaceAll('_',' '))}</span><h3>${esc(t.skill)}</h3><p>${esc(t.task)}</p><p class="muted">${esc(t.reason)}</p>${user.role==='student'?`<form class="progress-form" data-report="${p.id}" data-index="${t.index}"><label>Status<select name="status">${['not_started','in_progress','completed'].map(s=>`<option value="${s}" ${s===t.status?'selected':''}>${esc(s.replaceAll('_',' '))}</option>`).join('')}</select></label><label>Evidence / learning notes<textarea name="note" maxlength="2000" rows="3" placeholder="What did you build, solve or learn? Include an exercise or project reference.">${esc(t.note)}</textarea></label><button>Save progress</button></form>`:`<p><b>Student evidence:</b> ${esc(t.note||'No evidence notes yet.')}</p>`}${t.updated?`<small>Updated ${new Date(t.updated*1000).toLocaleString()}</small>`:''}</article>`).join('')}</section>`).join(''):'<section class="card empty"><h2>No approved roadmap yet</h2><p>Generate a preparation report in Resume workspace and have your placement officer approve it. Your tasks will then appear here.</p></section>'}`);
  document.querySelectorAll('.progress-form').forEach(form=>form.onsubmit=async event=>{
   event.preventDefault();const button=form.querySelector('button');button.disabled=true;
   try{await api('progress/update',{id:Number(form.dataset.report),index:Number(form.dataset.index),status:form.elements.status.value,note:form.elements.note.value});const y=window.scrollY;await progressScreen();window.scrollTo(0,y);notify('Preparation progress saved. Your placement officer can view it.')}catch(error){notify(error.message);button.disabled=false}
  });
 }catch(error){shell(`<section class="card"><p>${esc(error.message)}</p></section>`)}
}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,data){const r=await fetch('/api/'+path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const j=await r.json();if(!r.ok)throw Error(j.error);return j}
function notify(message){document.querySelector('#message').textContent=message}
function login(){if(window.interviewSpeech){window.interviewSpeech.abort();window.interviewSpeech=null;}if(window.speechSynthesis)window.speechSynthesis.cancel();root.innerHTML=`<main class="login"><section class="intro"><div class="brand">◈ ASCEND</div><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h1>Build your skills.<br>Find your direction.</h1><p>One place to understand your strengths, prepare with purpose, and take the next step toward your career.</p><div class="steps"><span>01 · Discover</span><span>02 · Practise</span><span>03 · Progress</span></div><small>Placement Readiness & Career Intelligence Portal</small></section><section class="signin"><div class="pill">STUDENT & PLACEMENT OFFICER PORTAL</div><h2>Welcome back</h2><p>Sign in with your student or placement officer account.</p><form id="login"><label>USN or Placement Officer ID<input name="usn" autocomplete="username" required placeholder="Enter your college ID"></label><label>Password<input type="password" name="password" autocomplete="current-password" required placeholder="Enter your password"></label><button>Sign in <span>→</span></button></form><p id="message" role="status"></p><button id="register" class="secondary">Student? Create your account</button>${setupRequired?`<button id="setup-officer" class="secondary">Initial placement officer setup</button>`:""}</section></main>`;document.querySelector('#register').onclick=()=>accountScreen(false);if(setupRequired)document.querySelector('#setup-officer').onclick=()=>accountScreen(true);document.querySelector('#login').onsubmit=async e=>{e.preventDefault();try{await api('login',Object.fromEntries(new FormData(e.target)));await start()}catch(err){notify(err.message)}}}
function shell(content){if(window.workspaceTimer)clearTimeout(window.workspaceTimer);if(window.interviewSpeech){window.interviewSpeech.abort();window.interviewSpeech=null;}if(window.speechSynthesis)window.speechSynthesis.cancel();if(window.practiceTimer)clearInterval(window.practiceTimer);root.innerHTML=`<aside><div class="brand">◈ ASCEND</div><small>CAREER WORKSPACE</small><nav><a id="profile-nav" class="selected">${user.role==='faculty'?'Submissions':'My profile'}</a><a id="resume-nav">Resume workspace</a><a id="connections-nav">Coding & GitHub</a><a id="reports-nav">Reports & preparation</a><a id="progress-nav">Preparation tracker</a><a id="planner-nav">Preparation planner</a>${user.role==='faculty'?'<a id="governance-nav">Versions & audit</a><a id="runtime-nav">Agent diagnostics</a>':''}<a id="coding-nav">Coding assessments</a><a id="practice-nav">Practice assessments</a><a id="interview-nav">${user.role==='faculty'?'Interview scores':'Interview studio'}</a></nav><div class="account"><b>${esc(user.name)}</b><small>${esc(user.id)} · ${esc(user.role)}</small><button id="logout" class="secondary">Sign out</button></div></aside><main class="workspace"><header><span>Placement Readiness / ${user.role==='faculty'?'Placement officer workspace':'Getting started'}</span></header>${content}<p id="message" role="status"></p></main>`;document.querySelector('#profile-nav').onclick=()=>user.role==='faculty'?faculty():student();document.querySelector('#resume-nav').onclick=resumeScreen;document.querySelector('#reports-nav').onclick=reportsScreen;document.querySelector('#connections-nav').onclick=connectionsScreen;document.querySelector('#practice-nav').onclick=practiceScreen;document.querySelector('#planner-nav').onclick=plannerScreen;const governanceNav=document.querySelector('#governance-nav');if(governanceNav)governanceNav.onclick=governanceScreen;const runtimeNav=document.querySelector('#runtime-nav');if(runtimeNav)runtimeNav.onclick=runtimeScreen;document.querySelector('#coding-nav').onclick=codingScreen;document.querySelector('#progress-nav').onclick=progressScreen;document.querySelector('#interview-nav').onclick=interviewStudio;document.querySelector('#logout').onclick=async()=>{await api('logout',{});login()}}
async function student(){const p=await api('profile');shell(`<section class="heading"><span class="eyebrow">YOUR FOUNDATION</span><h1>Let’s build your career profile.</h1><p>Start with your details and the direction you want to explore.</p></section><div class="grid"><section class="card"><h2>Profile & preferences</h2><p>Your college ID is linked to this account.</p><form id="profile"><div class="fields">${[['branch','Branch','Computer Science'],['graduation','Graduation year','2027'],['cgpa','CGPA (out of 10)','8.2'],['leetcode','LeetCode username or profile URL','Your public username'],['github','GitHub account (optional)','Username or https://github.com/username']].map(([key,label,placeholder])=>`<label>${label}<input name="${key}" value="${esc(p[key])}" placeholder="${placeholder}"></label>`).join('')}</div><label>Target role<select name="target">${['Software Engineer','Backend Developer','Frontend Developer','Data Analyst','Data Engineer','Core Engineering','Higher Studies'].map(v=>`<option ${p.target===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Job description (optional)<textarea name="jobDescription" rows="7" maxlength="15000" placeholder="Paste the role responsibilities, required skills and qualifications here…">${esc(p.jobDescription||'')}</textarea></label><p class="note">Used to compare your resume and project evidence with this role. Maximum 15,000 characters.</p><h3>Your data, your choice</h3><p>Choose which sources the portal may process. Save your consent before uploading a resume. GitHub is optional. Only public profile data is fetched; passwords or access tokens are not required.</p>${[['resumeConsent','Allow processing of my uploaded resume'],['codingConsent','Allow access to my coding-platform activity'],['githubConsent','Allow analysis of my public GitHub repositories (optional)'],['academicConsent','Allow processing of my academic details']].map(([k,label])=>`<label class="check"><input type="checkbox" name="${k}" ${p[k]?'checked':''}>${label}</label>`).join('')}<button>Save profile <span>→</span></button></form></section><section><div class="card accent"><span class="eyebrow">WHAT COMES NEXT</span><h2>A clearer path to placement.</h2><ol><li><b>Add your evidence</b><p>Resume, coding activity and academic details.</p></li><li><b>Discover your skill gaps</b><p>Compare your evidence with target-role requirements.</p></li><li><b>Prepare with a plan</b><p>Practise, assess and interview with guided feedback.</p></li><li><b>Review with your mentor</b><p>Your placement officer approves published readiness results.</p></li></ol></div><div class="note">After saving, open Resume workspace to upload your resume and request a faculty-reviewed preparation report. Assessments are upcoming.</div></section></div>`);document.querySelector('#profile').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));for(const k of ['resumeConsent','codingConsent','academicConsent','githubConsent'])d[k]=e.target.elements[k].checked;try{await api('profile',d);notify('Profile and consent saved successfully.')}catch(err){notify(err.message)}}}
async function faculty(){const rows=await api('submissions');shell(`<section class="heading"><span class="eyebrow">PLACEMENT CELL</span><h1>Student submissions</h1><p>Review student intake and preparation preferences.</p></section><section class="card"><h2>${rows.length} submitted profiles</h2>${rows.length?`<div class="tablewrap"><table><thead><tr><th>Student</th><th>USN</th><th>Branch</th><th>Target role</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.id)}</td><td>${esc(r.profile.branch)}</td><td>${esc(r.profile.target)}</td><td><span class="pill">Profile received</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No profiles yet. Student submissions will appear here after they save their intake details.</p>'}</section><div class="note">Open Reports & preparation to review reports, Preparation tracker for task updates, and Interview scores for Gemini results and recordings.</div>`)}
async function start(){const setup=await api('setup-status');setupRequired=setup.required;try{user=await api('me')}catch{login();return}try{await(user.role==='faculty'?faculty():student())}catch(err){root.textContent=err.message}}
start();

function accountScreen(setup){
 const content=`<section class="heading"><div class="brand">◈ ASCEND</div><h1>${setup?'Set up your placement portal':'Create student account'}</h1><p>${setup?'Create the first placement officer. This one-time setup closes after creation.':'Register with your USN and choose your own password. Your placement officer can review your profile after you submit it.'}</p></section><section class="card"><form id="account-form"><label>${setup?'Placement Officer ID':'Student USN'}<input name="id" required minlength="3" maxlength="40" pattern="[A-Za-z0-9_-]+" autocomplete="username"></label><label>Full name<input name="name" required minlength="2" maxlength="100"></label><label>Password (at least 12 characters)<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><label>Confirm password<input name="confirm" type="password" required autocomplete="new-password"></label><button>Create account →</button></form></section>`;
 root.innerHTML=`<main class="signin">${content}<p id="message" role="status"></p><button id="back-login" class="secondary">Back to sign in</button></main>`;document.querySelector("#back-login").onclick=login;
 document.querySelector('#account-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.password!==d.confirm){notify('Passwords do not match.');return}delete d.confirm;const button=e.target.querySelector('button');button.disabled=true;try{await api(setup?'setup':'register',d);if(setup)setupRequired=false;login();notify('Account created. Sign in with your ID and chosen password.')}catch(err){notify(err.message)}finally{button.disabled=false}};
}


async function resumeScreen(){
 if(user.role==='faculty'){await reportsScreen();return}
 let resume;try{resume=await api('resume')}catch(err){shell(`<section class="heading"><h1>Resume workspace</h1><p>${esc(err.message)}</p></section><button id="consent-link">Go to profile</button>`);document.querySelector('#consent-link').onclick=student;return}
 shell(`<section class="heading"><span class="eyebrow">YOUR EXPERIENCE, IN ONE PLACE</span><h1>Resume workspace</h1><p>Upload your resume, review the organised details, then request a preparation report.</p></section><div class="grid"><section class="card"><h2>${resume.name?esc(resume.name):'Add your resume'}</h2><p>PDF, DOCX or TXT · up to 2 MB. Scanned PDFs need text recognition first.</p><form id="upload-form"><label>Choose resume<input type="file" id="resume-file" accept=".pdf,.docx,.txt" required></label><button>Upload and extract</button></form>${resume.text?`<hr><h3>Ready for analysis</h3><p>Your selected role comes from your saved profile. The report will go to the placement officer first.</p><button id="run-analysis">Generate preparation report →</button>`:''}</section><section class="card"><h2>Your resume profile</h2>${resume.structured?structuredResume(resume.structured)+jdPanel(resume.jdMatch):'<p>Your organised resume details will appear here after upload.</p>'}</section></div>`);
 document.querySelector('#upload-form').onsubmit=async e=>{e.preventDefault();const file=document.querySelector('#resume-file').files[0];if(file.size>2*1024*1024){notify('Please choose a file smaller than 2 MB.');return}const button=e.target.querySelector('button');button.disabled=true;notify('Extracting your resume…');try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await api('resume',{filename:file.name,content});await resumeScreen();notify('Resume extracted and saved privately.')}catch(err){notify(err.message||'Could not read file')}finally{button.disabled=false}};
 const run=document.querySelector('#run-analysis');if(run)run.onclick=async()=>{run.disabled=true;notify('Analysing your resume and consented coding profiles. This can take up to 30 seconds…');try{await api('analyse',{requestId:run.dataset.requestId||(run.dataset.requestId=crypto.randomUUID())});await reportsScreen()}catch(err){notify(err.message);run.disabled=false}};
}
function reportDetail(r){const p=r.report;return `<div class="report-detail"><div class="metrics"><div><strong>${p.coverage}%</strong><span>Resume evidence coverage</span></div><div><strong>${p.found.length}</strong><span>Skills mentioned</span></div><div><strong>${p.gaps.length}</strong><span>Skills not evidenced</span></div></div><p>${esc(p.method)}</p><span class="pill">${esc(p.target)}</span><h3>Evidence from your resume</h3>${p.evidence.length?p.evidence.map(e=>`<div class="evidence"><b>${esc(e.skill)}</b><blockquote>${esc(e.excerpt)}</blockquote><small>${esc(e.source)} · ${esc(e.verification)}</small></div>`).join(''):'<p>No benchmark skills were detected. This does not establish that the student lacks these skills.</p>'}<h3>Preparation roadmap</h3>${p.roadmap.length?p.roadmap.map(t=>`<div class="evidence"><b>Week ${t.week} · ${esc(t.skill)}</b><p>${esc(t.task)}</p><small>${esc(t.reason)}</small></div>`).join(''):'<p>All sample benchmark skills are mentioned. Verify depth through assessments and project discussion.</p>'}${p.sources?`<h3>Coding & GitHub analysis</h3>${sourceCards(p.sources)}`:""}${p.projects?`<h3>Projects in brief</h3>${projectCards(p.projects)}`:""}${p.practice?`<h3>Practice assessment evidence</h3>${p.practice.length?p.practice.map(a=>`<p><b>${esc(a.kind)}:</b> ${a.correct}/${a.total} (${a.percentage}%). Practice only; not a readiness certification.</p>`).join(''):'<p>No submitted practice attempts at report generation.</p>'}`:""}${p.jdMatch?jdPanel(p.jdMatch):''}${p.execution?`<h3>Specialist execution trace</h3><p>${esc(p.execution.kind)} - ${p.execution.durationMs} ms - ${p.execution.parallelWorkers} parallel workers</p><small>Run ${esc(p.execution.id)}</small><ol>${p.trace.map(t=>`<li><b>${esc(t.stage)}</b>: ${esc(t.stage==='Placement officer approval'?r.status:t.status)}${t.durationMs!=null?' ('+t.durationMs+' ms)':''}<small> Depends on: ${esc((t.dependsOn||[]).join(', ')||'Start')}</small></li>`).join('')}</ol><h3>Acceptance checks</h3><ul>${Object.entries(p.validation).map(([k,v])=>`<li>${esc(k.replaceAll('_',' '))}: ${v?'Passed':'Failed'}</li>`).join('')}</ul>`:''}${p.coordinator?`<h3>Coordinator plan</h3><p>${esc(p.coordinator.planner)}: ${esc(p.coordinator.rationale)}</p>`:''}${p.revision?`<p>Revision of report #${p.revision.parent}: ${esc(p.revision.reason)}</p>`:''}<h3>Benchmark & limitations</h3><p>${esc(p.benchmark.source)} · ${esc(p.benchmark.version)}</p><ul>${p.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`}
async function reportsScreen(){try{const rows=await api('analyses');shell(`<section class="heading"><span class="eyebrow">${user.role==='faculty'?'PLACEMENT CELL REVIEW':'YOUR PREPARATION'}</span><h1>${user.role==='faculty'?'Review preparation reports':'Reports & preparation'}</h1><p>${user.role==='faculty'?'Inspect evidence and the sample benchmark before approving a report.':'Your approved preparation reports appear here. New drafts stay with your placement officer until reviewed.'}</p></section>${rows.length?rows.map(r=>`<section class="card report"><div class="report-top"><h2>${user.role==='faculty'?esc(r.name)+' · ':''}Report #${r.id}</h2><span class="pill">${esc(r.status.replaceAll('_',' '))}${r.isCurrent?' - Current publication':''}</span></div>${r.status==='approved'&&r.report?`<button class="secondary" data-export="${r.id}">Download approved report</button>`:''}<p>${new Date(r.created*1000).toLocaleString()}${r.reviewer?' · Reviewed by '+esc(r.reviewer):''}</p>${r.note?`<div class="note"><b>Officer feedback:</b> ${esc(r.note)}</div>`:''}${r.report?reportDetail(r):'<p>Your report is awaiting review. You can continue updating your profile.</p>'}${user.role==='faculty'&&r.status==='pending'?`<form class="review-form" data-id="${r.id}"><label>Review notes<textarea name="note" maxlength="2000" rows="3" placeholder="Feedback, benchmark suitability or corrections"></textarea></label><div class="actions"><button name="decision" value="approved">Approve & release</button><button name="decision" value="changes_requested" class="secondary">Request corrections</button></div></form>`:''}</section>`).join(''):'<section class="card empty"><h2>No preparation reports yet</h2><p>Upload a resume and generate a report to begin.</p></section>'}`);document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportReport(rows.find(r=>r.id===Number(b.dataset.export))));document.querySelectorAll('.review-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const decision=e.submitter.value;try{await api('review',{id:Number(form.dataset.id),decision,note:form.elements.note.value});await reportsScreen();notify(decision==='approved'?'Report approved and released to the student.':'Correction request saved.')}catch(err){notify(err.message)}})}catch(err){shell(`<section class="card"><p>${esc(err.message)}</p></section>`)}}
function linesCard(title,lines){return `<section class="resume-section"><h3>${title}</h3>${lines?.length?`<ul>${lines.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p class="muted">Not confidently detected in this resume.</p>'}</section>`}
function projectCards(projects){return projects?.length?projects.map(p=>`<article class="project-card"><div class="report-top"><h3>${esc(p.title)}</h3>${p.language?`<span class="pill">${esc(p.language)}</span>`:''}</div><p>${esc(p.summary||'No description provided.')}</p>${p.details?.length?`<details><summary>Full project description</summary><ul>${p.details.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></details>`:''}<small>${esc(p.source||'Resume')}${p.archived?' · Archived':''}</small></article>`).join(''):'<p>No project descriptions were confidently detected. Add a Projects section to your resume or connect GitHub.</p>'}
function structuredResume(s){return `<p class="note">${esc(s.notice)}</p>${linesCard('Personal details',s.personal?.lines)}${s.personal?.emails?.length?`<p><b>Email:</b> ${s.personal.emails.map(esc).join(', ')}</p>`:''}${s.personal?.phones?.length?`<p><b>Phone:</b> ${s.personal.phones.map(esc).join(', ')}</p>`:''}${linesCard('Academic details',s.academic)}<section class="resume-section"><h3>Projects</h3>${projectCards(s.projects)}</section>${linesCard('Experience & internships',s.experience)}${linesCard('Technical & extra skills',s.skills)}${linesCard('Certifications & achievements',s.extras)}${linesCard('Profile summary',s.summary)}`}
function sourceCards(sources){return ['leetcode','github'].map(source=>{const s=sources[source]||{status:'not_synced'};return `<article class="source-card"><div class="report-top"><h3>${source==='github'?'GitHub':'LeetCode'}${s.username?' · '+esc(s.username):''}</h3><span class="pill">${esc(s.status.replaceAll('_',' '))}</span></div><p>${esc(s.summary||s.message||'Not synced yet.')}</p>${s.fetched?`<small>Fetched ${new Date(s.fetched*1000).toLocaleString()}</small>`:''}${s.solved?`<div class="metrics">${['Easy','Medium','Hard'].map(k=>`<div><strong>${esc(s.solved[k]??'—')}</strong><span>${k} solved</span></div>`).join('')}</div><p>Active days in the last 30 days: ${esc(s.activeDaysLast30??'Unavailable')} · Provider-reported streak: ${esc(s.streak??'Unavailable')}</p>`:''}${s.languages?`<p><b>Primary repository languages:</b> ${Object.entries(s.languages).map(([k,v])=>esc(k)+' ('+v+')').join(', ')||'None reported'}</p>`:''}${s.limitations?`<ul class="muted">${s.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>`:''}</article>`}).join('')}
async function connectionsScreen(){if(user.role==='faculty'){await reportsScreen();return}try{const sources=await api('connections');shell(`<section class="heading"><span class="eyebrow">YOUR PRACTICAL EXPERIENCE</span><h1>Coding & GitHub</h1><p>Connect accounts in Profile & preferences, give consent, then sync public activity. GitHub is optional.</p><div class="actions"><button id="sync-profiles">Sync public profiles</button><button id="edit-connections" class="secondary">Edit accounts & consent</button></div></section><div id="source-results">${sourceCards(sources)}</div>${sources.github?.projects?`<section class="card"><h2>Public projects in brief</h2>${projectCards(sources.github.projects.slice(0,20))}<p class="note">Showing up to 20 project summaries from the fetched repository set.</p></section>`:''}`);document.querySelector('#edit-connections').onclick=student;document.querySelector('#sync-profiles').onclick=async e=>{e.target.disabled=true;notify('Fetching public profiles…');try{await api('connections',{});await connectionsScreen();notify('Sync finished. Check each source status. Generate a new report to include this snapshot.')}catch(err){notify(err.message);e.target.disabled=false}}}catch(err){shell(`<section class="card"><p>${esc(err.message)}</p></section>`)}}
async function practiceScreen(){try{const rows=await api('practice');shell(`<section class="heading"><span class="eyebrow">LEARN THROUGH PRACTICE</span><h1>${user.role==='faculty'?'Student practice history':'Practice assessments'}</h1><p>Objective marking, explanations and topic feedback. These are practice results, not certified readiness scores.</p></section>${user.role==='student'?`<label class="check"><input type="checkbox" id="practice-ai-consent">I consent to sending my resume excerpts, target role and JD to Google Gemini to generate personalised practice questions.</label><div class="grid"><section class="card"><span class="pill">20 MINUTES · 10 QUESTIONS</span><h2>Aptitude</h2><p>Percentages, ratios, reasoning, probability and verbal skills.</p><button data-start="aptitude">Start or resume aptitude →</button></section><section class="card"><span class="pill">20 MINUTES · 10 QUESTIONS</span><h2>Technical fundamentals</h2><p>Questions tailored to your resume skills, projects, target role and job description.</p><button data-start="technical">Start or resume technical →</button></section></div><p class="note">New questions and answer explanations are generated by Gemini for your profile. Complete your profile, JD and resume first. AI answer keys may contain errors; review explanations with your placement officer.</p>`:''}<section class="card"><h2>Attempt history</h2>${rows.length?`<div class="tablewrap"><table><thead><tr>${user.role==='faculty'?'<th>Student</th>':''}<th>Practice</th><th>Started</th><th>Status</th><th>Result</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr>${user.role==='faculty'?`<td>${esc(a.name)}<br>${esc(a.student)}</td>`:''}<td>${esc(a.kind)}</td><td>${new Date(a.started*1000).toLocaleString()}</td><td>${esc(a.status)}</td><td>${a.result?a.result.correct+'/'+a.result.total:'In progress'}</td><td><button class="secondary" data-attempt="${esc(a.id)}">${a.status==='active'?'Resume':'Review'}</button></td></tr>`).join('')}</tbody></table></div>`:'<p>No practice attempts yet.</p>'}</section>`);document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{notify('Preparing your personalised questions. The timer starts when they are ready.');renderAttempt(await api('practice/start',{kind:b.dataset.start,aiConsent:document.querySelector('#practice-ai-consent').checked}))}catch(err){notify(err.message);b.disabled=false}});document.querySelectorAll('[data-attempt]').forEach(b=>b.onclick=async()=>{try{renderAttempt(await api('practice/attempt',{id:b.dataset.attempt}))}catch(err){notify(err.message)}})}catch(err){shell(`<section class="card"><p>${esc(err.message)}</p></section>`)}}
function renderAttempt(a){if(a.status==='submitted'){practiceResult(a);return}const editable=user.role==='student';shell(`<section class="heading"><span class="eyebrow">${esc(a.kind.toUpperCase())} PRACTICE</span><h1>Focus on your next answer.</h1><div class="actions"><span class="pill" id="practice-clock"></span><span id="save-state" role="status">Answers saved on selection</span></div><p>One mark per correct answer. No negative marking. Unanswered questions receive zero. The timer continues if you leave this page.</p></section><form id="attempt-form">${a.questions.map((q,i)=>`<section class="card question-card"><span class="eyebrow">QUESTION ${i+1} / ${a.questions.length} · ${esc(q.topic)}</span><h2>${esc(q.prompt)}</h2>${q.options.map((option,index)=>`<label class="answer-option"><input type="radio" name="${esc(q.id)}" value="${index}" ${a.answers[q.id]===index?'checked':''} ${editable?'':'disabled'}><span>${esc(option)}</span></label>`).join('')}</section>`).join('')}${editable?'<button id="submit-practice">Submit practice</button>':''}</form><button id="back-practice" class="secondary">Back to practice history</button>`);const form=document.querySelector('#attempt-form');const answers=()=>Object.fromEntries([...new FormData(form)].map(([key,value])=>[key,Number(value)]));let queue=Promise.resolve();let submitting=false;const offset=a.serverTime*1000-Date.now();
 document.querySelector('#back-practice').onclick=async()=>{await queue;practiceScreen()};
 form.onchange=()=>{const snapshot=answers();document.querySelector('#save-state').textContent='Saving…';queue=queue.catch(()=>{}).then(async()=>{try{const updated=await api('practice/save',{id:a.id,answers:snapshot});if(updated.status==='submitted'){renderAttempt(updated);return}const el=document.querySelector('#save-state');if(el)el.textContent='All answers saved'}catch(err){const el=document.querySelector('#save-state');if(el)el.textContent='Save failed. Your choices will be retried when you submit.'}})};
 const submit=async()=>{if(submitting||!editable)return;submitting=true;const button=document.querySelector('#submit-practice');if(button)button.disabled=true;await queue;try{renderAttempt(await api('practice/submit',{id:a.id,answers:answers()}))}catch(err){notify(err.message);submitting=false;if(button)button.disabled=false}};
 form.onsubmit=e=>{e.preventDefault();submit()};
 const tick=()=>{const remaining=Math.max(0,Math.ceil((a.deadline*1000-Date.now()-offset)/1000));const clock=document.querySelector('#practice-clock');if(clock)clock.textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0')+' remaining';if(!remaining&&editable)submit()};tick();window.practiceTimer=setInterval(tick,1000);
}
function practiceResult(a){const r=a.result;shell(`<section class="heading"><span class="eyebrow">PRACTICE COMPLETE</span><h1>Your ${esc(a.kind)} feedback</h1><p>${esc(r.label)}</p></section><section class="card"><div class="metrics"><div><strong>${r.correct}/${r.total}</strong><span>Correct answers</span></div><div><strong>${r.percentage}%</strong><span>Practice score</span></div><div><strong>${r.answered}</strong><span>Questions answered</span></div></div><h3>What to work on next</h3>${r.nextSteps.length?`<ul>${r.nextSteps.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p>All questions answered correctly. Try another practice session or move to a more advanced exercise.</p>'}<p class="note">Generate a new preparation report to include this attempt and topic-specific preparation tasks for placement officer review.</p><button id="back-practice">Back to practice</button></section>${r.review.map((q,i)=>`<section class="card question-card"><span class="pill">${q.correct?'Correct':q.selected===null?'Unanswered':'Needs review'}</span><h3>${i+1}. ${esc(q.prompt)}</h3><p><b>Your answer:</b> ${esc(q.selected===null?'Not answered':q.options[q.selected])}</p><p><b>Correct answer:</b> ${esc(q.options[q.answer])}</p><p>${esc(q.explanation)}</p></section>`).join('')}`);document.querySelector('#back-practice').onclick=practiceScreen}
function jdPanel(j){if(!j||j.status==='no_jd')return `<section class="resume-section"><h3>Job description comparison</h3><p>Paste a JD below Target Role in Profile & preferences, then save to see your comparison here.</p></section>`;return `<section class="jd-panel"><span class="eyebrow">YOUR TARGET JOB</span><h2>Job description & resume match</h2><details open><summary>Job description you provided</summary><p class="jd-text">${esc(j.text)}</p></details><div class="metrics"><div><strong>${j.coverage===null?'N/A':j.coverage+'%'}</strong><span>Recognised JD skill coverage</span></div><div><strong>${j.matchedCount}</strong><span>Requirements evidenced</span></div><div><strong>${j.total}</strong><span>Recognised requirements</span></div></div><p class="note">${esc(j.method)} ${esc(j.notice)}</p>${j.coverage===null?'<p>No required skills could be reliably recognised from the current vocabulary. Review the JD manually; this is not a zero match.</p>':''}<h3>What matches your resume</h3>${j.requirements.filter(r=>r.matched).map(r=>`<div class="evidence"><b>${esc(r.skill)}</b> <span class="pill">${r.priority==='preferred'?'Preferred':'Required / unspecified'}</span><p><b>JD:</b> ${esc(r.jdEvidence)}</p><p><b>Resume:</b> ${r.resumeEvidence.map(esc).join(' · ')}</p></div>`).join('')||'<p>No recognised skill evidence found.</p>'}<h3>What to learn next — in brief</h3>${j.learnNext.length?`<ul>${j.learnNext.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p>No missing recognised required skills. This does not confirm experience depth or full eligibility.</p>'}${j.preferredMissing.length?`<p><b>Optional / preferred skills to explore:</b> ${j.preferredMissing.map(esc).join(', ')}</p>`:''}<h3>Do your projects support this JD?</h3>${j.projects.length?j.projects.map(p=>`<article class="project-card"><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><p><b>JD skill coverage in this project:</b> ${p.coverage===null?'N/A':p.coverage+'%'}</p><p><b>Related skills:</b> ${p.matched.map(esc).join(', ')||'None recognised in the description'}</p><p><b>Not evidenced in this project:</b> ${p.missing.map(esc).join(', ')||'None among recognised requirements'}</p><small>${esc(p.interpretation)}</small></article>`).join(''):'<p>No resume project sections detected. Add clearly headed project descriptions to compare them.</p>'}${j.manualReview.length?`<details><summary>Requirements needing manual review (${j.manualReview.length})</summary><ul>${j.manualReview.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}</section>`}
function exportReport(r){if(!r||r.status!=='approved'||!r.report)return;const p=r.report;const text=['PLACEMENT PREPARATION REPORT',`Report: ${r.id}`,`Student: ${r.student}`,`Approved by: ${r.reviewer||'Placement officer'}`,`Review note: ${r.note||'None'}`,`Target role: ${p.target}`,`Resume evidence coverage: ${p.coverage}%`,p.method,'','SKILL GAPS',...p.gaps,'','PREPARATION ROADMAP',...p.roadmap.map(t=>`Week ${t.week} - ${t.skill}\n${t.task}\nReason: ${t.reason}`),'','PROJECTS',...(p.projects||[]).map(t=>`${t.title}: ${t.summary}\nSource: ${t.source}`),'','JOB DESCRIPTION',p.jdMatch?.text||'Not provided',`JD recognised skill coverage: ${p.jdMatch?.coverage??'N/A'}${p.jdMatch?.coverage==null?'':'%'}`,'Missing JD skills: '+(p.jdMatch?.missing||[]).join(', '),'',...Object.entries(p.sources||{}).map(([k,v])=>`${k}: ${v.summary||v.message||v.status}`),'','LIMITATIONS',...p.limitations].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`preparation-report-${r.id}.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function interviewStudio(){try{
 const [config,rows]=await Promise.all([api('interviews/config'),api('interviews')]);
 shell(`<section class="heading"><span class="eyebrow">GEMINI INTERVIEW</span><h1>${user.role==='faculty'?'Interview scores & review':'Mock interview'}</h1><p>Ten Gemini-generated resume, JD, project and technical questions. Spoken answers are evaluated by Gemini using a question-specific rubric.</p></section>${user.role==='student'?`<section class="card"><h2>Ready to begin?</h2><p>Keep your camera and microphone on. Review the transcription before submitting each answer.</p>${!config.geminiConfigured?'<p class="note">Interviews are not connected yet. Ask your placement officer to connect Gemini in Interview scores.</p>':''}<button id="video-setup" ${config.geminiConfigured?'':'disabled'}>Start interview</button></section>`:`<section class="card"><h2>Gemini connection</h2><p><b>${config.geminiConfigured?'Connected - student interviews enabled':'Not connected'}</b></p><p>Paste your Gemini API key here. The model is selected automatically. A small connection-check request is sent to Google when you save.</p><form id="gemini-key-form"><label>${config.geminiConfigured?'Replace API key':'Gemini API key'}<input type="password" name="apiKey" autocomplete="off" spellcheck="false" minlength="20" maxlength="200" required placeholder="Paste your API key"></label><button>Save & test connection</button><p id="gemini-connection-status" role="status" aria-live="polite"></p></form><p class="note">Saved encrypted on this Windows computer. Students cannot view the key. No server restart is needed.</p></section>`}<section class="card question-card"><h2>${user.role==='faculty'?'Student interview results':'Interview history'}</h2>${rows.length?rows.map(r=>`<article class="evidence"><h3>${user.role==='faculty'?esc(r.name)+' ('+esc(r.student)+') - ':''}${esc(r.role)}</h3><p>${esc(r.status)} - ${r.answered}/${r.total} answers - ${new Date(r.created*1000).toLocaleString()}</p><p><b>${r.summary?.percentage!=null?(r.summary.complete?'Gemini score: ':'Partial Gemini score: ')+r.summary.percentage+' / 100':'No Gemini score available'}</b> - ${r.summary?.scored||0} scored answers</p><p>${r.review?'Officer: '+esc(r.review.decision.replaceAll('_',' ')):'Awaiting officer review'}</p><button class="secondary" data-interview="${esc(r.id)}">View answers, scores & recording</button></article>`).join(''):'<p>No interviews yet.</p>'}</section>`);
 const keyForm=document.querySelector('#gemini-key-form');if(keyForm)keyForm.onsubmit=async e=>{e.preventDefault();const button=keyForm.querySelector('button'),status=document.querySelector('#gemini-connection-status');button.disabled=true;button.textContent='Testing connection…';status.textContent='Contacting Gemini. Please wait; the automatic fallback can take up to a minute.';const apiKey=keyForm.elements.apiKey.value.trim();try{await api('interviews/provider',{apiKey});keyForm.elements.apiKey.value='';await interviewStudio();document.querySelector('#gemini-connection-status').textContent='Connection verified and key saved. Student AI features are enabled.';}catch(error){status.textContent='Connection was not saved: '+error.message;status.setAttribute('role','alert');status.scrollIntoView({block:'nearest'});button.disabled=false;button.textContent='Retry connection check';}};
 const start=document.querySelector('#video-setup');if(start)start.onclick=()=>videoSetup().catch(e=>notify(e.message));
 document.querySelectorAll('[data-interview]').forEach(b=>b.onclick=async()=>{try{renderInterview(await api('interviews/open',{id:b.dataset.interview}))}catch(e){notify(e.message)}});
 }catch(e){shell(`<section class="card"><p>${esc(e.message)}</p></section>`)}}

function interviewFeedback(turn){const f=turn.feedback;return `<section class="card question-card"><span class="eyebrow">${esc(turn.rubric?.category||'INTERVIEW ANSWER')}</span><h3>${esc(turn.question)}</h3><p class="jd-text">${esc(turn.answer)}</p>${turn.transcriptCorrected?`<details><summary>Student corrected the transcription</summary><p>${esc(turn.originalTranscript)}</p></details>`:''}<h3>${f.checklist?'Legacy guided feedback':'Gemini feedback'}</h3><p>${esc(f.feedback)}</p>${f.scorable===false?'<p class="note">Not scored: insufficient intelligible evidence.</p>':f.correctness!=null?`<p>Correctness ${f.correctness}/4 - Relevance ${f.relevance}/4 - Clarity ${f.clarity}/4 - Depth ${f.depth}/4</p>`:'<p>Legacy session: no current rubric score.</p>'}${f.strengths?`<p><b>What was good:</b> ${esc(f.strengths)}</p><p><b>Missing / incorrect:</b> ${esc(f.missing)}</p>`:''}<p><b>Improve:</b> ${esc(f.improvement)}</p>${f.exampleAnswer?`<details><summary>Illustrative answer from Gemini</summary><p>${esc(f.exampleAnswer)}</p><small>AI-generated example; not a verified answer key.</small></details>`:''}</section>`}
function renderInterviewText(s){const score=s.summary; shell(`<section class="heading"><span class="eyebrow">INTERVIEW RESULTS</span><h1>${esc(s.role)}</h1><p>${esc(s.status)} - ${s.answered}/${s.questions.length} answers saved</p></section><section class="card"><h2>${score?.percentage!=null?(score.complete?'Gemini score: ':'Partial Gemini score: ')+score.percentage+' / 100':'No scored answers yet'}</h2><p>${esc(score?.label||s.notice)}</p>${score?.dimensions?`<div class="metrics">${Object.entries(score.dimensions).map(([k,v])=>`<div><strong>${v}/4</strong><span>${esc(k)}</span></div>`).join('')}</div><p>${score.scored}/${score.total} answers scored. ${score.complete?'All questions evaluated.':'Interview incomplete or some answers unscorable.'}</p>`:''}${score?.nextSteps?.length?`<h3>Preparation next steps</h3><ul>${score.nextSteps.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}</section>${s.review?`<section class="card question-card"><h2>Placement officer review</h2><p>${esc(s.review.decision.replaceAll('_',' '))} by ${esc(s.review.reviewer)}</p><p>${esc(s.review.note)}</p></section>`:''}${user.role==='faculty'&&s.status!=='active'?`<section class="card question-card"><h2>Review Gemini's assessment</h2><p>Record corrections or follow-up needs. Original AI scores remain visible.</p><form id="officer-interview-review"><label>Decision<select name="decision"><option value="reviewed">Reviewed</option><option value="needs_followup">Needs follow-up</option></select></label><label>Officer feedback / corrections<textarea name="note" rows="4" minlength="10" maxlength="3000" required>${esc(s.review?.note||'')}</textarea></label><button>Save review</button></form></section>`:''}${user.role==='student'&&s.status==='active'?'<section class="card question-card"><p>This saved session has no active camera connection. End it and start a new camera interview.</p><button id="end-interview">End saved session</button></section>':''}<div id="recording-playback"></div><button id="interview-back" class="secondary">Back to interview history</button>${s.turns.map(interviewFeedback).join('')}`);
 document.querySelector('#interview-back').onclick=interviewStudio;loadRecording(s.id);
 const review=document.querySelector('#officer-interview-review');if(review)review.onsubmit=async e=>{e.preventDefault();const b=review.querySelector('button');b.disabled=true;try{renderInterviewText(await api('interviews/review',{id:s.id,decision:review.elements.decision.value,note:review.elements.note.value}));notify('Officer review saved.')}catch(e){notify(e.message);b.disabled=false}};
 const end=document.querySelector('#end-interview');if(end)end.onclick=async()=>{try{renderInterviewText(await api('interviews/end',{id:s.id}))}catch(e){notify(e.message)}};
}
let videoSession=null;
function renderInterview(s){if(videoSession&&videoSession.id===s.id){renderVideoInterview(s);return}renderInterviewText(s)}
async function videoSetup(){const config=await api('interviews/config');shell(`<section class="heading"><span class="eyebrow">CAMERA-ON MOCK INTERVIEW</span><h1>Check your camera and microphone</h1><p>Your camera and microphone stay on while you answer each question. The private recording is available to you and the placement officer.</p></section><section class="card"><form id="video-start-form"><label class="check"><input name="consent" type="checkbox" required>I consent to private video/audio recording and transcript storage, accessible to me and the placement officer.</label><label class="check"><input name="aiConsent" type="checkbox" required>I agree to send my spoken answers, relevant resume/JD excerpts and questions to Google Gemini for question generation, adaptive follow-ups, transcription, feedback and scoring.</label><p class="note">Tab changes and camera/microphone interruptions are logged for human review; they are not proof of cheating. Maximum recording size: 250 MB. End and save before leaving this page.</p><button ${config.geminiConfigured?'':'disabled'}>Begin interview</button>${config.geminiConfigured?'':'<p>Ask your placement officer to connect Gemini in Interview scores.</p>'}</form><p id="device-status" role="status"></p></section>`);document.querySelector('#video-start-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;let stream;let session;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('This browser cannot record video. Use a supported browser on localhost or HTTPS.');if(!config.geminiConfigured)throw Error('Gemini must be configured before an interview can begin.');if(!f.elements.aiConsent.checked)throw Error('Gemini voice-processing consent is required.');stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:960},height:{ideal:540}},audio:{echoCancellation:true,noiseSuppression:true}});const mime=['video/webm;codecs=vp8,opus','video/webm;codecs=vp9,opus','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime)throw Error('This browser does not support the required WebM recording format.');session=await api('interviews/start',{mode:'gemini',consent:true,aiConsent:f.elements.aiConsent.checked,audioConsent:f.elements.aiConsent.checked});await api('media/start',{id:session.id,consent:true,mime});const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:500000,audioBitsPerSecond:64000});videoSession={id:session.id,stream,recorder,sequence:0,queue:Promise.resolve(),error:null,stopping:false,started:Date.now()};const v=videoSession;v.uploader=new RecordingUploader(packet=>api('media/chunk',{id:v.id,...packet}));recorder.ondataavailable=event=>{if(event.data.size)v.uploader.add(event.data).catch(err=>{const status=document.querySelector('#video-status');if(status)status.textContent='Upload paused: '+err.message+'. Retry saving to reconnect.'})};recorder.onerror=()=>{v.error='Browser recording failed';logVideoEvent('recording_interrupted')};v.visibility=()=>{if(document.hidden)logVideoEvent('tab_hidden')};v.unload=e=>{if(!v.stopping){e.preventDefault();e.returnValue='End and save your interview before leaving.'}};v.blur=()=>{if(!v.stopping)logVideoEvent('window_blur')};window.addEventListener('blur',v.blur);document.addEventListener('visibilitychange',v.visibility);window.addEventListener('beforeunload',v.unload);stream.getTracks().forEach(track=>{track.onended=()=>{if(!v.stopping)logVideoEvent(track.kind==='video'?'camera_ended':'microphone_ended')};track.onmute=()=>{if(!v.stopping)logVideoEvent(track.kind==='video'?'camera_muted':'microphone_muted')}});recorder.start(4000);renderVideoInterview(session)}catch(err){if(stream)stream.getTracks().forEach(t=>t.stop());if(session)await api('interviews/end',{id:session.id}).catch(()=>{});document.querySelector('#device-status').textContent=err.name==='NotAllowedError'?'Camera or microphone permission was denied. Allow both in the browser site settings, then try again.':err.name==='NotFoundError'?'No camera or microphone was found. Connect both devices and try again.':err.name==='NotReadableError'?'The camera or microphone is busy. Close other apps using it and try again.':err.message;b.disabled=false}}}
function logVideoEvent(event){if(videoSession)videoSession.reviewEvents=(videoSession.reviewEvents||0)+1;if(videoSession)api('media/event',{id:videoSession.id,event}).catch(()=>{});const status=document.querySelector('#video-status');if(status)status.textContent='Review event logged: '+event.replaceAll('_',' ')+'. This is not an automatic malpractice finding.'}
async function finishVideo(state){const v=videoSession;if(!v||v.stopping)return;v.stopping=true;if(v.monitorTimer)clearInterval(v.monitorTimer);if(v.answerRecorder&&v.answerRecorder.state!=='inactive')v.answerRecorder.stop();window.removeEventListener('blur',v.blur);document.removeEventListener('visibilitychange',v.visibility);if(window.interviewSpeech)window.interviewSpeech.stop();await new Promise(resolve=>{if(v.recorder.state==='inactive'){resolve();return}v.recorder.addEventListener('stop',resolve,{once:true});v.recorder.stop()});v.stream.getTracks().forEach(t=>t.stop());let error;try{await v.uploader.flush();if(v.error)throw Error(v.error);await api('media/finish',{id:v.id})}catch(err){error=err.message}if(error){v.stopping=false;notify('Answers saved. Recording upload paused: '+error+'. Keep this page open and click Retry saving recording.');const retry=document.querySelector('#video-end');if(retry){retry.disabled=false;retry.textContent='Retry saving recording';retry.onclick=()=>finishVideo(state)}return}window.removeEventListener('beforeunload',v.unload);videoSession=null;renderInterviewText(state);notify('Interview and private recording saved.')}
function renderVideoInterview(s){
 if(s.status!=='active'){finishVideo(s);return}
 const v=videoSession;let answering=false;let answerRecorder=null;let audioParts=[];let savedAudio=null;
 if(v.monitorTimer)clearInterval(v.monitorTimer);
 const source=s.questionSources?.[s.answered];
 shell(`<div class="interview-workspace"><div class="voice-top"><span class="recording-badge">● PRIVATE VIDEO INTERVIEW</span><span>Question ${s.answered+1} / ${s.questions.length}</span></div><div class="interview-split"><section class="live-camera-box"><video id="camera-preview" autoplay muted playsinline></video><span class="camera-label">You · live camera</span><div class="device-strip"><span id="camera-health">Camera connecting…</span><span id="microphone-health">Microphone checking…</span></div></section><section class="compact-question"><span class="eyebrow">QUESTION ${s.answered+1}</span><h2>${esc(s.questions[s.answered])}</h2>${source?`<p class="question-source">Based on: ${esc(source.source)} · ${esc(source.topic)}</p>`:''}<p id="voice-prompt">Click Start answering and speak. Your face stays visible on the left.</p><button id="voice-answer">Start answering</button><button id="video-next" disabled>${s.answered===s.questions.length-1?'Finish interview':'Next question →'}</button><button id="video-read" class="secondary">Hear question</button><div id="transcript-review"></div><p id="voice-status" role="status">${s.mode==='gemini'?'Gemini will transcribe your audio and provide feedback.':'Your spoken answer is saved for officer review. Guided mode does not evaluate speech.'}</p></section></div><div class="interview-bottom"><p id="video-status" role="status">Recording active · tab switches and device interruptions logged for review.</p><button id="video-end" class="secondary">End & save recording</button></div></div>`);
 document.querySelectorAll('aside nav a, #logout').forEach(el=>{el.onclick=e=>{e.preventDefault();notify('End and save the recording before leaving.')}});
 const preview=document.querySelector('#camera-preview');preview.srcObject=v.stream;preview.play().catch(()=>{document.querySelector('#camera-health').textContent='Camera preview paused — click the video to play';preview.onclick=()=>preview.play()});
 const health=()=>{const camera=v.stream.getVideoTracks()[0],mic=v.stream.getAudioTracks()[0];const c=document.querySelector('#camera-health'),m=document.querySelector('#microphone-health');if(c)c.textContent=camera?.readyState==='live'&&camera.enabled&&!camera.muted?'Camera on':'Camera interrupted';if(m)m.textContent=mic?.readyState==='live'&&mic.enabled&&!mic.muted?'Microphone on':'Microphone interrupted';{const st=document.querySelector('#video-status');if(st)st.textContent=v.error||v.uploader.error?'Upload paused: '+(v.error||v.uploader.error):'Recording active - '+v.uploader.sequence+' chunks saved; '+v.uploader.pending.length+' pending.'}};health();v.monitorTimer=setInterval(health,1000);
 const status=()=>document.querySelector('#voice-status');
 document.querySelector('#video-read').onclick=()=>{if(window.speechSynthesis){window.speechSynthesis.cancel();window.speechSynthesis.speak(new SpeechSynthesisUtterance(s.questions[s.answered]))}};
 document.querySelector('#voice-answer').onclick=()=>{
  if(window.speechSynthesis)window.speechSynthesis.cancel();
  if(v.stream.getTracks().some(t=>t.readyState!=='live'||!t.enabled||t.muted)){notify('Camera or microphone is interrupted. Check permissions and devices.');return}
  try{
   if(s.mode==='gemini'){
    const mime=['audio/webm;codecs=opus','audio/webm'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime)throw Error('Audio encoding for Gemini is unavailable. Use a browser supporting WebM audio, such as Chrome or Edge.');
    audioParts=[];savedAudio=null;answerRecorder=new MediaRecorder(new MediaStream(v.stream.getAudioTracks()),{mimeType:mime,audioBitsPerSecond:48000});v.answerRecorder=answerRecorder;answerRecorder.ondataavailable=e=>{if(e.data.size)audioParts.push(e.data)};answerRecorder.start(1000);
   }
   answering=true;document.querySelector('#video-read').disabled=true;document.querySelector('#video-next').disabled=false;document.querySelector('#voice-answer').disabled=true;document.querySelector('#voice-answer').textContent='Answer recording…';document.querySelector('#voice-prompt').textContent='Speak now. Click Review spoken answer when you finish.';status().textContent='Listening through your microphone. Keep answers within about two minutes.';
  }catch(err){notify(err.message)}
 };
 document.querySelector('#video-next').onclick=async()=>{
  if(!answering||v.stopping)return;if(v.stream.getTracks().some(t=>t.readyState!=='live'||!t.enabled||t.muted)){notify('Restore camera and microphone before continuing.');return}if(v.error){notify('Recording upload failed: '+v.error);return}
  const button=document.querySelector('#video-next');const endButton=document.querySelector('#video-end');button.disabled=true;endButton.disabled=true;
  try{
   await v.uploader.flush();const payload={id:s.id,index:s.answered,answer:'[Spoken answer captured in private interview recording; no text transcript supplied.]'};
   if(s.mode==='gemini'){
    if(!savedAudio){if(answerRecorder.state!=='inactive')await new Promise(resolve=>{answerRecorder.addEventListener('stop',resolve,{once:true});answerRecorder.stop()});const blob=new Blob(audioParts,{type:answerRecorder.mimeType});if(blob.size>2*1024*1024)throw Error('This answer exceeds 2 MB. End the session and use shorter answers.');savedAudio={audio:await blobBase64(blob),audioMime:answerRecorder.mimeType};}Object.assign(payload,savedAudio);
   }
   status().textContent='Transcribing your answer…';const draft=await api('interviews/draft',payload);showTranscript(draft.transcript);endButton.disabled=false;
  }catch(err){try{const latest=await api('interviews/open',{id:s.id});if(latest.answered>s.answered||latest.status!=='active'){renderVideoInterview(latest);return}if(latest.draft?.index===s.answered){showTranscript(latest.draft.transcript);endButton.disabled=false;return}}catch{}notify(err.message);button.disabled=false;button.textContent='Retry saving answer';endButton.disabled=false}
 };
 function showTranscript(transcript){
  document.querySelector('#video-next').disabled=true;document.querySelector('#voice-answer').disabled=true;
  status().textContent='Check misheard words, then submit. Corrections are visible to the placement officer.';
  document.querySelector('#transcript-review').innerHTML=`<form id="confirm-transcript"><label>Review your spoken answer<textarea name="answer" rows="5" minlength="5" maxlength="6000" required>${esc(transcript)}</textarea></label><button>${s.answered===s.questions.length-1?'Confirm & finish interview':'Confirm & next question'}</button></form>`;
  document.querySelector('#confirm-transcript').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button'),end=document.querySelector('#video-end');b.disabled=true;end.disabled=true;try{renderVideoInterview(await api('interviews/answer',{id:s.id,index:s.answered,answer:form.elements.answer.value}))}catch(error){try{const latest=await api('interviews/open',{id:s.id});if(latest.answered>s.answered||latest.status!=='active'){renderVideoInterview(latest);return}}catch{}notify(error.message);b.disabled=false;end.disabled=false}};
 }
 if(s.draft?.index===s.answered)showTranscript(s.draft.transcript);
 document.querySelector('#video-end').onclick=async()=>{try{await finishVideo(await api('interviews/end',{id:s.id}))}catch(err){notify(err.message)}};
}

async function loadRecording(id){try{const info=await api('media/info?id='+encodeURIComponent(id));const el=document.querySelector('#recording-playback');if(!el||!info.id)return;const events=JSON.parse(info.events||'[]');el.innerHTML=`<section class="card question-card"><h2>Private interview recording</h2>${info.status==='complete'?`<video class="saved-interview-video" controls preload="metadata" src="/api/media/play?id=${encodeURIComponent(id)}"></video>`:info.status==='deleted'?'<p>Recording permanently deleted. Interview answers and review remain saved.</p>':'<p>Recording is incomplete.</p>'}<p>${events.length} review events. These are not automatic cheating findings.</p><ul>${events.map(e=>`<li>${esc(e.event.replaceAll('_',' '))} - ${new Date(e.at*1000).toLocaleString()}</li>`).join('')}</ul>${info.status!=='deleted'?'<button id="delete-recording" class="secondary">Delete this recording</button><p class="note">Deletion is permanent. Keep only recordings needed for assessment review; review retention after 30 days.</p>':''}</section>`;const remove=document.querySelector('#delete-recording');if(remove)remove.onclick=async()=>{if(!confirm('Permanently delete this video/audio recording? The transcript and scores will remain.'))return;remove.disabled=true;try{await api('media/delete',{id,confirm:true});await loadRecording(id);notify('Recording deleted.')}catch(error){notify(error.message);remove.disabled=false}}}catch{}}
